1	//! `ActiveReflectionCatalog` — the bridge-owned mutable layer that
2	//! tonic-reflection's immutable `Builder` cannot be (whitepaper: "Why
3	//! tonic-reflection Builder Is Not Enough").
4	//!
5	//! The catalog owns active plugin blobs and answers reflection queries:
6	//! `list_services` advertises only active blobs (no phantom services);
7	//! `file_by_filename` / `symbol_by_name` serve borrowed descriptor bytes
8	//! sliced straight out of the sealed blob images (zero-copy).
9	//!
10	//! Persistence is the per-object shm layout that replaces monolithic
11	//! `/dev/shm/live-schema.json`:
12	//!
13	//! ```text
14	//! /dev/shm/opdbus/plugin-blobs/<plugin_id>.<schema_hash16>.blob
15	//! ```
16	
17	use crate::blob::{BlobManifest, BlobRef, PluginObjectBlob};
18	use crate::descriptor;
19	use std::collections::HashMap;
20	use std::io;
21	use std::path::{Path, PathBuf};
22	
23	pub const DEFAULT_SHM_DIR: &str = "/dev/shm/opdbus/plugin-blobs";
24	
25	struct Entry {
26	    path: PathBuf,
27	    /// Sealed blob image; descriptor lookups return subslices of this.
28	    bytes: Vec<u8>,
29	    manifest: BlobManifest,
30	    /// file name -> (offset, len) of the FileDescriptorProto within `bytes`.
31	    files: HashMap<String, (usize, usize)>,
32	    /// fully-qualified symbol -> file name.
33	    symbols: HashMap<String, String>,
34	}
35	
36	pub struct ActiveReflectionCatalog {
37	    dir: PathBuf,
38	    entries: HashMap<String, Entry>,
39	}
40	
41	/// Durable blob store. It keeps the historical `BlobStore` name while allowing
42	/// typed blob families in one store namespace. Today the active-reflection
43	/// family is backed by `ActiveReflectionCatalog`.
44	pub struct BlobStore {
45	    active_reflection: ActiveReflectionCatalog,
46	}
47	
48	impl BlobStore {
49	    pub fn open(dir: impl Into<PathBuf>) -> io::Result<Self> {
50	        Ok(Self {
51	            active_reflection: ActiveReflectionCatalog::open(dir)?,
52	        })
53	    }
54	
55	    pub fn open_default() -> io::Result<Self> {
56	        Self::open(DEFAULT_SHM_DIR)
57	    }
58	
59	    pub fn write(&mut self, blob: &PluginObjectBlob) -> io::Result<PathBuf> {
60	        match blob.manifest.blob_type.as_str() {
61	            "active_reflection" => self.active_reflection.upsert_blob(blob),
62	            other => Err(io::Error::new(
63	                io::ErrorKind::InvalidInput,
64	                format!("unsupported blob type: {other}"),
65	            )),
66	        }
67	    }
68	
69	    pub fn remove_blob(&mut self, plugin_id: &str) -> io::Result<bool> {
70	        self.active_reflection.remove_blob(plugin_id)
71	    }
72	
73	    pub fn list_services(&self) -> Vec<String> {
74	        self.active_reflection.list_services()
75	    }
76	
77	    pub fn active_plugins(&self) -> Vec<String> {
78	        self.active_reflection.active_plugins()
79	    }
80	
81	    pub fn manifest(&self, plugin_id: &str) -> Option<&BlobManifest> {
82	        self.active_reflection.manifest(plugin_id)
83	    }
84	
85	    pub fn blob_paths(&self) -> Vec<PathBuf> {
86	        self.active_reflection.blob_paths()
87	    }
88	
89	    pub fn active_reflection(&self) -> &ActiveReflectionCatalog {
90	        &self.active_reflection
91	    }
92	}
93	
94	impl ActiveReflectionCatalog {
95	    /// Open (and create) a catalog directory, loading any existing blobs.
96	    pub fn open(dir: impl Into<PathBuf>) -> io::Result<Self> {
97	        let dir = dir.into();
98	        std::fs::create_dir_all(&dir)?;
99	        let mut cat = Self {
100	            dir: dir.clone(),
101	            entries: HashMap::new(),
102	        };
103	        for e in std::fs::read_dir(&dir)? {
104	            let path = e?.path();
105	            if path.extension().and_then(|x| x.to_str()) == Some("blob") {
106	                if let Err(err) = cat.load_file(&path) {
107	                    // A corrupt blob must not take the catalog down; it is
108	                    // simply not advertised.
109	                    eprintln!("op-blob: skipping {}: {err}", path.display());
110	                }
111	            }
112	        }
113	        Ok(cat)
114	    }
115	
116	    /// Default runtime location on tmpfs (REQ-8.3: never Btrfs-backed I/O).
117	    pub fn open_shm() -> io::Result<Self> {
118	        Self::open(DEFAULT_SHM_DIR)
119	    }
120	
121	    fn load_file(&mut self, path: &Path) -> Result<(), String> {
122	        let bytes = std::fs::read(path).map_err(|e| e.to_string())?;
123	        let entry = index_entry(path.to_path_buf(), bytes)?;
124	        self.entries.insert(entry.manifest.plugin_id.clone(), entry);
125	        Ok(())
126	    }
127	
128	    /// Whitepaper lifecycle steps 10–12: persist the sealed blob, drop stale
129	    /// hash versions of the same plugin, rebuild the reflection index.
130	    pub fn upsert_blob(&mut self, blob: &PluginObjectBlob) -> io::Result<PathBuf> {
131	        let path = blob.write_to_dir(&self.dir)?;
132	        // Remove superseded hash versions on disk.
133	        let prefix = format!("{}.", blob.manifest.plugin_id);
134	        for e in std::fs::read_dir(&self.dir)? {
135	            let p = e?.path();
136	            if p != path {
137	                if let Some(name) = p.file_name().and_then(|n| n.to_str()) {
138	                    if name.starts_with(&prefix) && name.ends_with(".blob") {
139	                        let _ = std::fs::remove_file(&p);
140	                    }
141	                }
142	            }
143	        }
144	        let bytes = std::fs::read(&path)?;
145	        let entry = index_entry(path.clone(), bytes)
146	            .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;
147	        self.entries.insert(blob.manifest.plugin_id.clone(), entry);
148	        Ok(path)
149	    }
150	
151	    /// Inverse lifecycle: deactivate the plugin object, delete the artifact,
152	    /// stop advertising its services.
153	    pub fn remove_blob(&mut self, plugin_id: &str) -> io::Result<bool> {
154	        match self.entries.remove(plugin_id) {
155	            Some(entry) => {
156	                if entry.path.exists() {
157	                    std::fs::remove_file(&entry.path)?;
158	                }
159	                Ok(true)
160	            }
161	            None => Ok(false),
162	        }
163	    }
164	
165	    /// Reflection `ListServices`: only active blobs, sorted.
166	    pub fn list_services(&self) -> Vec<String> {
167	        let mut v: Vec<String> = self
168	            .entries
169	            .values()
170	            .flat_map(|e| e.manifest.grpc.services.iter().cloned())
171	            .collect();
172	        v.sort();
173	        v
174	    }
175	
176	    pub fn active_plugins(&self) -> Vec<String> {
177	        let mut v: Vec<String> = self.entries.keys().cloned().collect();
178	        v.sort();
179	        v
180	    }
181	
182	    /// Reflection `file_by_filename`: borrowed `FileDescriptorProto` bytes.
183	    pub fn file_by_filename(&self, filename: &str) -> Option<&[u8]> {
184	        self.entries.values().find_map(|e| {
185	            e.files
186	                .get(filename)
187	                .map(|(off, len)| &e.bytes[*off..*off + *len])
188	        })
189	    }
190	
191	    /// Reflection `file_containing_symbol`.
192	    pub fn symbol_by_name(&self, symbol: &str) -> Option<&[u8]> {
193	        self.entries.values().find_map(|e| {
194	            e.symbols
195	                .get(symbol)
196	                .and_then(|file| e.files.get(file))
197	                .map(|(off, len)| &e.bytes[*off..*off + *len])
198	        })
199	    }
200	
201	    pub fn manifest(&self, plugin_id: &str) -> Option<&BlobManifest> {
202	        self.entries.get(plugin_id).map(|e| &e.manifest)
203	    }
204	
205	    pub fn dir(&self) -> &Path {
206	        &self.dir
207	    }
208	
209	    /// Paths of all active blob artifacts (input to btrfs sealing).
210	    pub fn blob_paths(&self) -> Vec<PathBuf> {
211	        let mut v: Vec<PathBuf> = self.entries.values().map(|e| e.path.clone()).collect();
212	        v.sort();
213	        v
214	    }
215	}
216	
217	fn index_entry(path: PathBuf, bytes: Vec<u8>) -> Result<Entry, String> {
218	    let (manifest, files) = {
219	        let blob = BlobRef::new(&bytes)?;
220	        let manifest = blob.manifest()?;
221	        let set = blob.descriptor_set();
222	        let set_start = set.as_ptr() as usize - bytes.as_ptr() as usize;
223	        let mut files = HashMap::new();
224	        for f in descriptor::decode_file_summaries(set)? {
225	            let off = f.bytes.as_ptr() as usize - set.as_ptr() as usize;
226	            files.insert(f.name.clone(), (set_start + off, f.bytes.len()));
227	        }
228	        (manifest, files)
229	    };
230	    let mut symbols = HashMap::new();
231	    for m in &manifest.methods {
232	        for s in &m.symbols {
233	            symbols.insert(s.clone(), m.grpc_file.clone());
234	        }
235	    }
236	    Ok(Entry {
237	        path,
238	        bytes,
239	        manifest,
240	        files,
241	        symbols,
242	    })
243	}
