1	//! `PluginObjectBlob` — the sealed, self-describing projection of one
2	//! `PluginSchema` into one runtime identity (whitepaper "Target Data Model").
3	//!
4	//! The blob couples the four identities that must not drift:
5	//! schema identity (canonical JSON + sha256), D-Bus identity, gRPC identity,
6	//! and the reflection descriptor identity. It is deliberately redundant at the
7	//! blob boundary: schema stays authoritative, but the blob is self-describing
8	//! enough that reflection, GUI, compliance, and dispatch reason about the same
9	//! object without reassembling identity from scattered files.
10	//!
11	//! ## Sealed byte format (zero-copy)
12	//!
13	//! ```text
14	//! offset  size  content
15	//! 0       8     magic "OPBLOB01"
16	//! 8       2     format version (u16 LE) = 1
17	//! 10      2     section count (u16 LE)
18	//! 12      4     reserved
19	//! 16      32    sha256 of the SCHEMA_JSON section (the schema hash)
20	//! 48      16    reserved
21	//! 64      24*n  section table: tag u32, reserved u32, offset u64, len u64
22	//! ...           8-byte-aligned section payloads
23	//! ```
24	//!
25	//! Sections: 1 = canonical `PluginSchema` JSON, 2 = `BlobManifest` JSON,
26	//! 3 = protobuf `FileDescriptorSet`, 4 = compliance/extra metadata JSON.
27	//!
28	//! `BlobRef` verifies magic + hash once, then hands out borrowed slices —
29	//! reads never copy or re-parse the payload. Sealed bytes are fully
30	//! deterministic for the same schema (sorted maps, no timestamps), so the
31	//! schema hash doubles as the artifact identity in the filename:
32	//! `<plugin_id>.<hash16>.blob`.
33	
34	use crate::descriptor;
35	use crate::schema::{hex, PluginSchema, SideEffect};
36	use serde::{Deserialize, Serialize};
37	use sha2::{Digest, Sha256};
38	use std::io;
39	use std::path::{Path, PathBuf};
40	
41	pub const MAGIC: &[u8; 8] = b"OPBLOB01";
42	pub const FORMAT_VERSION: u16 = 1;
43	
44	pub const SECTION_SCHEMA_JSON: u32 = 1;
45	pub const SECTION_MANIFEST_JSON: u32 = 2;
46	pub const SECTION_DESCRIPTOR_SET: u32 = 3;
47	pub const SECTION_META_JSON: u32 = 4;
48	
49	const HEADER_LEN: usize = 64;
50	const SECTION_ENTRY_LEN: usize = 24;
51	
52	/// D-Bus identity carried by the blob (REQ-7.1/7.2).
53	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
54	pub struct DbusIdentity {
55	    pub bus_name: String,
56	    pub object_path: String,
57	    pub interface_name: String,
58	}
59	
60	/// gRPC identity: per-method packages/services synthesized from the schema.
61	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
62	pub struct GrpcIdentity {
63	    /// Fully-qualified service names, sorted.
64	    pub services: Vec<String>,
65	    /// Descriptor file names, sorted (parallel to services).
66	    pub files: Vec<String>,
67	}
68	
69	/// Per-method manifest entry copied from `PluginSchema.methods` plus the
70	/// synthesized gRPC identity — the compliance/audit unit.
71	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
72	pub struct MethodManifest {
73	    pub schema_name: String,
74	    pub grpc_name: String,
75	    pub grpc_path: String,
76	    pub grpc_service: String,
77	    pub grpc_file: String,
78	    pub input_message: String,
79	    pub output_message: String,
80	    pub subid: String,
81	    pub required_capability: Option<String>,
82	    pub side_effect: SideEffect,
83	    pub idempotent: bool,
84	    /// Fully-qualified symbols the method's descriptor file defines.
85	    pub symbols: Vec<String>,
86	}
87	
88	/// The blob's self-describing metadata (section 2).
89	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
90	pub struct BlobManifest {
91	    /// Runtime blob class. Serialized as `type` so the store can hold active
92	    /// reflection blobs now and other blob families later without guessing.
93	    #[serde(rename = "type", default = "default_blob_type")]
94	    pub blob_type: String,
95	    pub plugin_id: String,
96	    pub schema_version: String,
97	    pub schema_hash: String,
98	    pub dbus: DbusIdentity,
99	    pub grpc: GrpcIdentity,
100	    /// WireGuard-keypair identity of the publishing account (public half
101	    /// only); its session persists for the life of the account.
102	    #[serde(default)]
103	    pub identity: Option<crate::identity::BlobIdentity>,
104	    pub methods: Vec<MethodManifest>,
105	}
106	
107	fn default_blob_type() -> String {
108	    "active_reflection".to_string()
109	}
110	
111	/// Owned, unsealed blob. `seal()` produces the immutable byte image.
112	#[derive(Debug, Clone)]
113	pub struct PluginObjectBlob {
114	    pub manifest: BlobManifest,
115	    /// Canonical `PluginSchema` JSON (the authoritative contract bytes).
116	    pub schema_json: String,
117	    /// Encoded `google.protobuf.FileDescriptorSet` for all plugin methods.
118	    pub descriptor_set: Vec<u8>,
119	    /// Compliance / extra metadata (subids, immutable paths, dialect …).
120	    pub meta_json: String,
121	}
122	
123	/// Canonical D-Bus path form: lowercase, hyphens -> underscores.
124	pub fn canonical_plugin_id(name: &str) -> String {
125	    name.to_lowercase().replace('-', "_")
126	}
127	
128	/// Freeze one `PluginSchema` into a `PluginObjectBlob` (whitepaper "Blob
129	/// Creation Pipeline" steps 3–9). The schema is the input and stays the
130	/// authority; nothing here invents contract data.
131	pub fn blobify(schema: &PluginSchema) -> PluginObjectBlob {
132	    blobify_with_identity(schema, None)
133	}
134	
135	/// `blobify`, stamping the publishing account's WireGuard-keypair identity
136	/// (public half only) into the manifest.
137	pub fn blobify_with_identity(
138	    schema: &PluginSchema,
139	    identity: Option<crate::identity::BlobIdentity>,
140	) -> PluginObjectBlob {
141	    let plugin_id = canonical_plugin_id(&schema.name);
142	    let schema_json = schema.canonical_json();
143	    let schema_hash = {
144	        let mut h = Sha256::new();
145	        h.update(schema_json.as_bytes());
146	        hex(&h.finalize())
147	    };
148	
149	    let (descriptor_set, method_infos) = descriptor::descriptor_set_for_plugin(&plugin_id, schema);
150	
151	    let mut methods: Vec<MethodManifest> = method_infos
152	        .iter()
153	        .map(|d| {
154	            let decl = schema
155	                .methods
156	                .get(&d.method_name)
157	                .or_else(|| schema.methods.values().find(|m| m.name == d.method_name))
158	                .expect("descriptor method must come from PluginSchema.methods");
159	            MethodManifest {
160	                schema_name: decl.name.clone(),
161	                grpc_name: descriptor::pascal_case(&decl.name),
162	                grpc_path: d.grpc_path.clone(),
163	                grpc_service: d.service_full.clone(),
164	                grpc_file: d.file_name.clone(),
165	                input_message: d.input_full.clone(),
166	                output_message: d.output_full.clone(),
167	                subid: decl.subid.clone(),
168	                required_capability: decl.required_capability.clone(),
169	                side_effect: decl.side_effect,
170	                idempotent: decl.idempotent,
171	                symbols: d.symbols.clone(),
172	            }
173	        })
174	        .collect();
175	    methods.sort_by(|a, b| a.schema_name.cmp(&b.schema_name));
176	
177	    let mut services: Vec<String> = methods.iter().map(|m| m.grpc_service.clone()).collect();
178	    services.sort();
179	    let mut files: Vec<String> = methods.iter().map(|m| m.grpc_file.clone()).collect();
180	    files.sort();
181	
182	    let manifest = BlobManifest {
183	        blob_type: default_blob_type(),
184	        plugin_id: plugin_id.clone(),
185	        schema_version: schema.version.clone(),
186	        schema_hash,
187	        dbus: DbusIdentity {
188	            bus_name: "org.opdbus.v1.plugins".to_string(),
189	            object_path: format!("/org/opdbus/v1/plugins/{plugin_id}"),
190	            interface_name: "org.opdbus.v1.Plugin".to_string(),
191	        },
192	        grpc: GrpcIdentity { services, files },
193	        identity,
194	        methods,
195	    };
196	
197	    let meta = serde_json::json!({
198	        "blob_format": FORMAT_VERSION,
199	        "dialect": schema.dialect,
200	        "subids": schema.subids,
201	        "immutable_paths": schema.immutable_paths,
202	        "json_schema": schema.to_json_schema(),
203	    });
