213	impl PluginObjectBlob {
214	    /// Seal into the immutable byte image. Deterministic: same schema, same bytes.
215	    pub fn seal(&self) -> Vec<u8> {
216	        let manifest_json =
217	            serde_json::to_string(&serde_json::to_value(&self.manifest).unwrap()).unwrap();
218	        let sections: [(u32, &[u8]); 4] = [
219	            (SECTION_SCHEMA_JSON, self.schema_json.as_bytes()),
220	            (SECTION_MANIFEST_JSON, manifest_json.as_bytes()),
221	            (SECTION_DESCRIPTOR_SET, &self.descriptor_set),
222	            (SECTION_META_JSON, self.meta_json.as_bytes()),
223	        ];
224	
225	        let table_len = sections.len() * SECTION_ENTRY_LEN;
226	        let mut offset = align8(HEADER_LEN + table_len);
227	        let mut entries = Vec::with_capacity(sections.len());
228	        for (tag, bytes) in &sections {
229	            entries.push((*tag, offset as u64, bytes.len() as u64));
230	            offset = align8(offset + bytes.len());
231	        }
232	
233	        let mut out = Vec::with_capacity(offset);
234	        out.extend_from_slice(MAGIC);
235	        out.extend_from_slice(&FORMAT_VERSION.to_le_bytes());
236	        out.extend_from_slice(&(sections.len() as u16).to_le_bytes());
237	        out.extend_from_slice(&[0u8; 4]);
238	        let mut h = Sha256::new();
239	        h.update(self.schema_json.as_bytes());
240	        out.extend_from_slice(&h.finalize());
241	        out.extend_from_slice(&[0u8; 16]);
242	        debug_assert_eq!(out.len(), HEADER_LEN);
243	
244	        for (tag, off, len) in &entries {
245	            out.extend_from_slice(&tag.to_le_bytes());
246	            out.extend_from_slice(&[0u8; 4]);
247	            out.extend_from_slice(&off.to_le_bytes());
248	            out.extend_from_slice(&len.to_le_bytes());
249	        }
250	
251	        for ((_, bytes), (_, off, _)) in sections.iter().zip(&entries) {
252	            while out.len() < *off as usize {
253	                out.push(0);
254	            }
255	            out.extend_from_slice(bytes);
256	        }
257	        out
258	    }
259	
260	    /// `<plugin_id>.<hash16>.blob` — hash-addressed filename (shm layout).
261	    pub fn file_name(&self) -> String {
262	        format!(
263	            "{}.{}.blob",
264	            self.manifest.plugin_id,
265	            &self.manifest.schema_hash[..16]
266	        )
267	    }
268	
269	    pub fn write_to_dir(&self, dir: &Path) -> io::Result<PathBuf> {
270	        std::fs::create_dir_all(dir)?;
271	        let path = dir.join(self.file_name());
272	        std::fs::write(&path, self.seal())?;
273	        Ok(path)
274	    }
275	}
276	
277	fn align8(n: usize) -> usize {
278	    (n + 7) & !7
279	}
280	
281	/// Zero-copy view over sealed blob bytes. Construction verifies magic,
282	/// bounds, and the schema hash once; accessors return borrowed slices.
283	pub struct BlobRef<'a> {
284	    bytes: &'a [u8],
285	    sections: Vec<(u32, usize, usize)>,
286	}
287	
288	impl<'a> BlobRef<'a> {
289	    pub fn new(bytes: &'a [u8]) -> Result<Self, String> {
290	        if bytes.len() < HEADER_LEN || &bytes[..8] != MAGIC {
291	            return Err("not an OPBLOB01 blob".into());
292	        }
293	        let version = u16::from_le_bytes([bytes[8], bytes[9]]);
294	        if version != FORMAT_VERSION {
295	            return Err(format!("unsupported blob format version {version}"));
296	        }
297	        let count = u16::from_le_bytes([bytes[10], bytes[11]]) as usize;
298	        let table_end = HEADER_LEN + count * SECTION_ENTRY_LEN;
299	        if bytes.len() < table_end {
300	            return Err("section table overruns blob".into());
301	        }
302	        let mut sections = Vec::with_capacity(count);
303	        for i in 0..count {
304	            let e = HEADER_LEN + i * SECTION_ENTRY_LEN;
305	            let tag = u32::from_le_bytes(bytes[e..e + 4].try_into().unwrap());
306	            let off = u64::from_le_bytes(bytes[e + 8..e + 16].try_into().unwrap()) as usize;
307	            let len = u64::from_le_bytes(bytes[e + 16..e + 24].try_into().unwrap()) as usize;
308	            if off + len > bytes.len() {
309	                return Err(format!("section {tag} overruns blob"));
310	            }
311	            sections.push((tag, off, len));
312	        }
313	        let blob = Self { bytes, sections };
314	
315	        // Verify schema hash (blob-drift guard).
316	        let schema = blob
317	            .section(SECTION_SCHEMA_JSON)
318	            .ok_or("missing schema section")?;
319	        let mut h = Sha256::new();
320	        h.update(schema);
321	        if h.finalize().as_slice() != &bytes[16..48] {
322	            return Err("schema hash mismatch: blob is corrupt or tampered".into());
323	        }
324	        Ok(blob)
325	    }
326	
327	    fn section(&self, tag: u32) -> Option<&'a [u8]> {
328	        self.sections
329	            .iter()
330	            .find(|(t, _, _)| *t == tag)
331	            .map(|(_, off, len)| &self.bytes[*off..*off + *len])
332	    }
333	
334	    /// Canonical `PluginSchema` JSON — borrowed, zero-copy.
335	    pub fn schema_json(&self) -> &'a str {
336	        std::str::from_utf8(self.section(SECTION_SCHEMA_JSON).unwrap())
337	            .expect("schema section is UTF-8")
338	    }
339	
340	    pub fn manifest_json(&self) -> &'a str {
341	        std::str::from_utf8(self.section(SECTION_MANIFEST_JSON).unwrap())
342	            .expect("manifest section is UTF-8")
343	    }
344	
345	    /// Encoded `FileDescriptorSet` — borrowed, zero-copy; slices of this can
346	    /// be served directly to reflection clients.
347	    pub fn descriptor_set(&self) -> &'a [u8] {
348	        self.section(SECTION_DESCRIPTOR_SET).unwrap_or(&[])
349	    }
350	
351	    pub fn meta_json(&self) -> Option<&'a str> {
352	        self.section(SECTION_META_JSON)
353	            .and_then(|b| std::str::from_utf8(b).ok())
354	    }
355	
356	    pub fn schema_hash_hex(&self) -> String {
357	        hex(&self.bytes[16..48])
358	    }
359	
360	    /// Parse the manifest (the one intentional allocation on the read path;
361	    /// everything else stays borrowed).
362	    pub fn manifest(&self) -> Result<BlobManifest, String> {
363	        serde_json::from_str(self.manifest_json()).map_err(|e| format!("manifest parse: {e}"))
364	    }
365	
