1	//! opblob — drive the schema→blob→catalog→btrfs pipeline from the shell.
2	//!
3	//! ```text
4	//! opblob demo-seal <dir>              blobify demo plugins into a catalog dir
5	//! opblob seal-shm                     blobify real plugins into /dev/shm/opdbus/plugin-blobs
6	//! opblob seal-plugins <dir>           blobify real plugins into a catalog dir
7	//! opblob inspect <file.blob>          print identity, services, methods
8	//! opblob catalog <dir>                list active services in a catalog dir
9	//! opblob btrfs-seal <image> <dir>     seal a catalog dir into a btrfs image
10	//! opblob keygen <keyfile>             generate the account WG identity keypair
11	//! ```
12	
13	use op_blob::{
14	    blob, blobify_plugin_schema, btrfs,
15	    catalog::{ActiveReflectionCatalog, DEFAULT_SHM_DIR},
16	    demo, descriptor,
17	    identity::WgKeypair,
18	    BlobRef,
19	};
20	use op_plugins::DefaultPluginRegistry;
21	use op_state_store::MemoryStore;
22	use std::path::{Path, PathBuf};
23	use std::process::ExitCode;
24	use std::sync::Arc;
25	
