1	//! SHM Writer: Sole writer of plugin capability schemas and present-state to
2	//! shared memory.
3	//!
4	//! This module implements the producer side of the SHM pipeline.  It is the
5	//! **only** component that writes the live schema monolith, materialized
6	//! per-plugin schema views, the catalog hash manifest, and present-state
7	//! snapshots to `/dev/shm/opdbus/`.
8	//!
9	//! # Layout
10	//!
11	//! ```text
12	//! /dev/shm/
13	//! ├── live-schema.json                         ← combined monolith (all plugins)
14	//! └── opdbus/
15	//!     ├── .manifest.json                        ← { "catalog_hash": "<blake3>" }
16	//!     ├── schemas/
17	//!     │   ├── wireguard.json                    ← materialized plugin schema
18	//!     │   ├── xray.json
19	//!     │   └── ...
20	//!     └── state/
21	//!         ├── wireguard.json                    ← present-state snapshot
22	//!         ├── xray.json
23	//!         └── ...
24	//! ```
25	//!
26	//! # Atomicity
27	//!
28	//! The monolith and manifest are written atomically: data is first written to
29	//! a `.tmp` file and then renamed over the final path.  This prevents consumers
30	//! from reading a partial file.
31	//!
32	//! # Catalog Hash
33	//!
34	//! The Blake3 catalog hash is computed from `live-schema.json`. Only the
35	//! producer computes this hash; consumers read it from `.manifest.json`.
36	
37	use anyhow::{Context, Result};
38	use op_state_store::PluginSchema;
39	use std::collections::HashMap;
40	use std::fs;
41	use std::io::Write;
42	use std::path::{Path, PathBuf};
43	use tracing::{debug, info};
44	
45	/// Default base directory for shared memory.
46	const DEFAULT_SHM_BASE: &str = "/dev/shm";
47	
48	/// Subdirectory under the SHM base for all opdbus files.
49	const OPDBUS_DIR: &str = "opdbus";
50	
51	/// Subdirectory for materialized per-plugin schema views.
52	const SCHEMAS_DIR: &str = "schemas";
53	
54	/// Subdirectory for per-plugin present-state files.
55	const STATE_DIR: &str = "state";
56	
57	/// Combined monolith filename (lives directly under SHM base, not opdbus/).
58	const MONOLITH_FILENAME: &str = "live-schema.json";
59	
60	/// Manifest filename (lives under opdbus/).
61	const MANIFEST_FILENAME: &str = ".manifest.json";
62	
63	/// Sole writer of plugin capability schemas and present-state to SHM.
64	pub struct ShmWriter {
65	    /// Base directory (default `/dev/shm`).
66	    base_dir: PathBuf,
67	    /// `/dev/shm/opdbus`
68	    opdbus_dir: PathBuf,
69	    /// `/dev/shm/opdbus/schemas`
70	    schemas_dir: PathBuf,
71	    /// `/dev/shm/opdbus/state`
72	    state_dir: PathBuf,
73	    /// `/dev/shm/live-schema.json`
74	    monolith_path: PathBuf,
75	    /// `/dev/shm/opdbus/.manifest.json`
76	    manifest_path: PathBuf,
77	}
78	
79	impl Default for ShmWriter {
80	    fn default() -> Self {
81	        Self::new(DEFAULT_SHM_BASE)
82	    }
83	}
84	
85	impl ShmWriter {
86	    /// Creates a new `ShmWriter` rooted at the given base directory.
87	    ///
88	    /// In production, use `ShmWriter::default()` which targets `/dev/shm`.
89	    /// Tests should supply a temporary directory.
90	    pub fn new(base: impl AsRef<Path>) -> Self {
91	        let base_dir = base.as_ref().to_path_buf();
92	        let opdbus_dir = base_dir.join(OPDBUS_DIR);
93	        let schemas_dir = opdbus_dir.join(SCHEMAS_DIR);
94	        let state_dir = opdbus_dir.join(STATE_DIR);
95	        let monolith_path = base_dir.join(MONOLITH_FILENAME);
96	        let manifest_path = opdbus_dir.join(MANIFEST_FILENAME);
97	        Self {
98	            base_dir,
99	            opdbus_dir,
100	            schemas_dir,
101	            state_dir,
102	            monolith_path,
103	            manifest_path,
104	        }
105	    }
106	
107	    /// Returns the base directory path (e.g. `/dev/shm`).
108	    pub fn base_dir(&self) -> &Path {
109	        &self.base_dir
110	    }
111	
112	    /// Returns the opdbus directory path.
113	    pub fn opdbus_dir(&self) -> &Path {
114	        &self.opdbus_dir
115	    }
116	
117	    /// Returns the schemas directory path.
118	    pub fn schemas_dir(&self) -> &Path {
119	        &self.schemas_dir
120	    }
121	
122	    /// Returns the state directory path.
123	    pub fn state_dir(&self) -> &Path {
124	        &self.state_dir
125	    }
126	
127	    /// Returns the monolith file path.
128	    pub fn monolith_path(&self) -> &Path {
129	        &self.monolith_path
130	    }
131	
132	    /// Returns the manifest file path.
133	    pub fn manifest_path(&self) -> &Path {
134	        &self.manifest_path
135	    }
136	
137	    /// Creates the `/dev/shm/opdbus/` hierarchy (`schemas/`, `state/`) if it
138	    /// does not already exist.  Idempotent.
139	    pub fn ensure_dirs(&self) -> Result<()> {
140	        fs::create_dir_all(&self.opdbus_dir)
141	            .with_context(|| format!("failed to create {}", self.opdbus_dir.display()))?;
142	        fs::create_dir_all(&self.schemas_dir)
143	            .with_context(|| format!("failed to create {}", self.schemas_dir.display()))?;
144	        fs::create_dir_all(&self.state_dir)
145	            .with_context(|| format!("failed to create {}", self.state_dir.display()))?;
146	        Ok(())
147	    }
148	
149	    /// Writes a single materialized plugin schema JSON file to
150	    /// `/dev/shm/opdbus/schemas/<plugin_id>.json`.
151	    pub fn write_plugin_schema(&self, plugin_id: &str, schema: &PluginSchema) -> Result<()> {
152	        let path = self.schemas_dir.join(format!("{}.json", plugin_id));
153	        let json_bytes = serde_json::to_vec_pretty(schema)
154	            .with_context(|| format!("failed to serialize schema for '{}'", plugin_id))?;
155	        atomic_write(&path, &json_bytes)
156	            .with_context(|| format!("failed to write schema for '{}'", plugin_id))?;
157	        debug!(plugin_id, path = %path.display(), "wrote materialized plugin schema");
158	        Ok(())
159	    }
160	
161	    /// Writes the combined monolith to `/dev/shm/live-schema.json` atomically.
162	    ///
163	    /// `schemas` is a map of `plugin_id → PluginSchema` containing every plugin
164	    /// that returned `Some(schema)` from `schema()`.
165	    pub fn write_monolith(&self, schemas: &HashMap<String, PluginSchema>) -> Result<()> {
166	        let json_bytes =
167	            serde_json::to_vec_pretty(schemas).context("failed to serialize monolith")?;
168	        atomic_write(&self.monolith_path, &json_bytes).with_context(|| {
169	            format!(
170	                "failed to write monolith to {}",
171	                self.monolith_path.display()
172	            )
173	        })?;
174	        debug!(path = %self.monolith_path.display(), "wrote combined monolith");
175	        Ok(())
176	    }
177	
178	    /// Computes the Blake3 catalog hash over the live schema monolith.
179	    pub fn compute_catalog_hash(&self) -> Result<String> {
180	        let bytes = fs::read(&self.monolith_path)
181	            .with_context(|| format!("cannot read {}", self.monolith_path.display()))?;
182	        Ok(blake3::hash(&bytes).to_hex().to_string())
183	    }
184	
185	    /// Writes `{ "catalog_hash": "<hex>" }` to `.manifest.json` atomically.
186	    pub fn write_manifest(&self, catalog_hash: &str) -> Result<()> {
187	        let json = serde_json::json!({ "catalog_hash": catalog_hash });
188	        let json_bytes =
189	            serde_json::to_vec_pretty(&json).context("failed to serialize manifest")?;
190	        atomic_write(&self.manifest_path, &json_bytes).with_context(|| {
191	            format!(
192	                "failed to write manifest to {}",
193	                self.manifest_path.display()
194	            )
195	        })?;
196	        debug!(catalog_hash, path = %self.manifest_path.display(), "wrote manifest");
197	        Ok(())
198	    }
199	
200	    /// Writes present-state JSON for a plugin to
201	    /// `/dev/shm/opdbus/state/<plugin_id>.json`.
202	    pub fn write_present_state(&self, plugin_id: &str, state: &serde_json::Value) -> Result<()> {
203	        let path = self.state_dir.join(format!("{}.json", plugin_id));
204	        let json_bytes = serde_json::to_vec_pretty(state)
205	            .with_context(|| format!("failed to serialize present-state for '{}'", plugin_id))?;
206	        atomic_write(&path, &json_bytes)
207	            .with_context(|| format!("failed to write present-state for '{}'", plugin_id))?;
208	        debug!(plugin_id, path = %path.display(), "wrote present-state");
209	
210	        Ok(())
211	    }
212	
213	    /// Convenience: writes materialized plugin schema views, the combined
214	    /// monolith, and the manifest in one call.
215	    ///
216	    /// Plugins returning `None` from `schema()` are skipped entirely — no
217	    /// per-plugin file, no monolith entry, no state file.
218	    pub fn write_all_schemas(&self, plugins: &[(String, Option<PluginSchema>)]) -> Result<()> {
219	        self.ensure_dirs()?;
220	
221	        let mut monolith: HashMap<String, PluginSchema> = HashMap::new();
222	        for (plugin_id, schema_opt) in plugins {
223	            match schema_opt {
224	                Some(schema) => {
225	                    self.write_plugin_schema(plugin_id, schema)?;
226	                    monolith.insert(plugin_id.clone(), schema.clone());
227	                }
228	                None => {
229	                    debug!(plugin_id, "skipping plugin with None schema");
230	                }
231	            }
232	        }
233	
234	        self.write_monolith(&monolith)?;
235	        let hash = self.compute_catalog_hash()?;
236	        self.write_manifest(&hash)?;
237	
238	        info!(
239	            plugin_count = monolith.len(),
240	            catalog_hash = %hash,
241	            "wrote live schema and materialized plugin schemas to SHM"
242	        );
243	        Ok(())
244	    }
245	
246	    /// Convenience: writes present-state for all provided plugins.
247	    pub fn write_all_present_states(&self, states: &[(String, serde_json::Value)]) -> Result<()> {
248	        self.ensure_dirs()?;
249	        for (plugin_id, state) in states {
250	            let path = self.state_dir.join(format!("{}.json", plugin_id));
251	            let json_bytes = serde_json::to_vec_pretty(state).with_context(|| {
252	                format!("failed to serialize present-state for '{}'", plugin_id)
253	            })?;
254	            atomic_write(&path, &json_bytes)
255	                .with_context(|| format!("failed to write present-state for '{}'", plugin_id))?;
256	        }
257	        info!(state_count = states.len(), "wrote present-states to SHM");
258	        Ok(())
259	    }
260	}
261	
262	/// Atomically writes `data` to `path` by first writing to `<path>.tmp` and
263	/// then renaming over the target.
264	///
265	/// The rename(2) syscall is atomic on the same filesystem, so consumers will
266	/// never observe a partially written file.
267	fn atomic_write(path: &Path, data: &[u8]) -> Result<()> {
268	    let tmp_path = atomic_tmp_path(path);
269	    {
270	        let mut file = fs::File::create(&tmp_path)
271	            .with_context(|| format!("cannot create tmp file {}", tmp_path.display()))?;
272	        file.write_all(data)
273	            .with_context(|| format!("failed to write tmp file {}", tmp_path.display()))?;
274	        file.sync_all()
275	            .with_context(|| format!("failed to sync tmp file {}", tmp_path.display()))?;
276	    }
277	    fs::rename(&tmp_path, path).with_context(|| {
278	        format!(
279	            "failed to rename {} → {}",
280	            tmp_path.display(),
281	            path.display()
282	        )
283	    })?;
284	    Ok(())
285	}
286	
287	/// Returns the temporary path for atomic writes: `<path>.tmp`.
288	fn atomic_tmp_path(path: &Path) -> PathBuf {
289	    let mut tmp = path.to_path_buf();
290	    let mut name = tmp
291	        .file_name()
292	        .unwrap_or_default()
293	        .to_string_lossy()
294	        .to_string();
295	    name.push_str(".tmp");
296	    tmp.set_file_name(name);
297	    tmp
298	}
