417	    // ── VAL-PROD-002: combined monolith ─────────────────────────────────
418	
419	    #[test]
420	    fn producer_writes_combined_monolith() {
421	        let writer = test_writer();
422	        let plugins = vec![
423	            ("alpha".to_string(), Some(test_schema("alpha"))),
424	            ("beta".to_string(), Some(test_schema("beta"))),
425	            ("gamma".to_string(), None),
426	        ];
427	        writer
428	            .write_all_schemas(&plugins)
429	            .expect("write_all_schemas");
430	
