432	        let monolith: serde_json::Value = serde_json::from_str(&monolith_text).unwrap();
433	        let obj = monolith.as_object().unwrap();
434	        assert!(obj.contains_key("alpha"), "monolith must contain alpha");
435	        assert!(obj.contains_key("beta"), "monolith must contain beta");
436	        assert!(
437	            !obj.contains_key("gamma"),
438	            "monolith must NOT contain gamma (None schema)"
439	        );
440	        assert_eq!(obj.len(), 2, "monolith must have exactly 2 plugins");
441	
442	        // Monolith entries contain capability surface
443	        assert!(monolith["alpha"]["methods"].is_object());
444	        assert!(monolith["alpha"]["signals"].is_array());
445	        assert!(monolith["alpha"]["guarantees"].is_object());
446	
447	        cleanup(&writer);
448	    }
449	
450	    // ── VAL-PROD-003: manifest hash matches independent recompute ───────
451	
452	    #[test]
453	    fn producer_manifest_hash_matches_recompute() {
454	        let writer = test_writer();
455	        let plugins = vec![
456	            ("alpha".to_string(), Some(test_schema("alpha"))),
457	            ("beta".to_string(), Some(test_schema("beta"))),
458	        ];
