473	        );
474	
475	        // Verify hash changes when a schema file is modified
476	        let alpha_path = writer.schemas_dir.join("alpha.json");
477	        fs::write(&alpha_path, b"{\"changed\":true}").unwrap();
478	        let recomputed2 = writer.compute_catalog_hash().expect("recompute2");
479	        assert_ne!(
480	            recomputed, recomputed2,
481	            "hash must change when a schema file changes"
482	        );
483	
484	        cleanup(&writer);
485	    }
486	
487	    // ── VAL-PROD-004: present-state on state change ─────────────────────
488	
489	    #[test]
490	    fn producer_updates_present_state_on_change() {
491	        let writer = test_writer();
492	        let plugins = vec![("alpha".to_string(), Some(test_schema("alpha")))];
493	        writer
494	            .write_all_schemas(&plugins)
495	            .expect("write_all_schemas");
496	
497	        // Read initial manifest hash
498	        let manifest_text = fs::read_to_string(writer.manifest_path()).unwrap();
499	        let manifest: serde_json::Value = serde_json::from_str(&manifest_text).unwrap();
500	        let hash_before = manifest["catalog_hash"].as_str().unwrap().to_string();
501	
502	        // Write present-state
