509	        let state_path = writer.state_dir.join("alpha.json");
510	        assert!(state_path.exists(), "state file should exist");
511	        let state_text = fs::read_to_string(&state_path).unwrap();
512	        let state_json: serde_json::Value = serde_json::from_str(&state_text).unwrap();
513	        assert_eq!(state_json["status"], "active");
514	        assert_eq!(state_json["uptime"], 42);
515	
