517	        // but manifest is rewritten — hash should be same since schema
518	        // files didn't change)
519	        let manifest_text2 = fs::read_to_string(writer.manifest_path()).unwrap();
520	        let manifest2: serde_json::Value = serde_json::from_str(&manifest_text2).unwrap();
521	        let hash_after = manifest2["catalog_hash"].as_str().unwrap().to_string();
