9	/// Strongly-typed error for D-Bus mirror operations.
10	///
11	/// Keeps `anyhow` out of the public API surface while preserving
12	/// ergonomic `?` propagation inside the crate.
13	#[derive(Debug, thiserror::Error)]
14	pub enum MirrorError {
15	    #[error("D-Bus error: {0}")]
16	    Zbus(#[from] zbus::Error),
17	
18	    #[error("serialization error: {0}")]
19	    Serialization(#[from] serde_json::Error),
20	
21	    #[error("{0}")]
22	    Other(String),
23	}
24	
25	impl From<anyhow::Error> for MirrorError {
26	    fn from(e: anyhow::Error) -> Self {
27	        Self::Other(e.to_string())
28	    }
29	}
