110	    /// Performs an initial full-tree publication and then enters an event-driven
111	    /// loop to publish deltas from all data sources.
112	    pub async fn start(self: Arc<Self>) -> std::result::Result<(), MirrorError> {
113	        tracing::info!("Starting D-Bus mirror publication service...");
114	
115	        // Register ObjectManager at the root to manage EVERYTHING.
116	        let om = ObjectManagerInterface::new(self.plugin_registry.clone());
