16	/// Event dispatcher that wires all event sources to the broadcast channel
17	pub struct EventDispatcher {
18	    pub broadcast_tx: broadcast::Sender<MirrorEvent>,
19	    mirror: Arc<DbusMirror>,
20	    ovsdb_client: Arc<OvsdbDbusClient>,
21	    grpc_server: Option<Arc<op_grpc_bridge::OperationGrpcServer>>,
22	    /// Sequence numbers per object path
23	    sequence_numbers: Arc<std::sync::Mutex<HashMap<String, u64>>>,
24	}
25	
26	impl EventDispatcher {
27	    /// Create a new EventDispatcher
28	    pub fn new(
29	        mirror: Arc<DbusMirror>,
30	        ovsdb_client: Arc<OvsdbDbusClient>,
31	        grpc_server: Option<Arc<op_grpc_bridge::OperationGrpcServer>>,
32	    ) -> Self {
33	        let (broadcast_tx, _) = broadcast::channel(1000);
34	        Self {
35	            broadcast_tx,
36	            mirror,
37	            ovsdb_client,
38	            grpc_server,
39	            sequence_numbers: Arc::new(std::sync::Mutex::new(HashMap::new())),
40	        }
41	    }
42	
43	    /// Spawn all event sources
44	    pub async fn spawn_event_sources(&self) -> Result<()> {
45	        info!("Spawning all event sources");
46	
47	        // Spawn OVSDB monitor
48	        ovsdb::spawn_ovsdb_monitor(self.ovsdb_client.clone(), self.broadcast_tx.clone()).await?;
49	
50	        // Spawn procfs watchers
51	        procfs::spawn_procfs_inotify_watchers(self.broadcast_tx.clone()).await?;
52	        procfs::spawn_procfs_loadavg_timer(self.broadcast_tx.clone()).await?;
53	
54	        // Spawn ComponentRegistry watcher
55	        if let Some(grpc) = &self.grpc_server {
56	            component_registry::spawn_component_registry_watcher(
57	                grpc.clone(),
58	                self.broadcast_tx.clone(),
59	            )
60	            .await?;
61	        }
62	
63	        Ok(())
64	    }
65	
66	    /// Run the event loop
67	    pub async fn run_event_loop(&self) -> Result<()> {
68	        info!("Starting event loop");
69	
70	        let mut rx = self.broadcast_tx.subscribe();
71	
72	        loop {
73	            match rx.recv().await {
74	                Ok(event) => {
