69	pub fn blobify_plugin_schema(
70	    plugin_id: &str,
71	    schema: op_state_store::PluginSchema,
72	) -> PluginObjectBlob {
73	    let mut schema = state_store_schema_to_blob_schema(schema);
74	    schema.name = plugin_id.to_string();
75	    blobify(&schema)
76	}
