78	pub fn blobify_plugin_schema_with_identity(
79	    plugin_id: &str,
80	    schema: op_state_store::PluginSchema,
81	    identity: Option<BlobIdentity>,
82	) -> PluginObjectBlob {
83	    let mut schema = state_store_schema_to_blob_schema(schema);
84	    schema.name = plugin_id.to_string();
85	    blobify_with_identity(&schema, identity)
86	}
87	
88	fn state_store_schema_to_blob_schema(schema: op_state_store::PluginSchema) -> PluginSchema {
89	    let value = serde_json::to_value(schema).expect("op-state-store PluginSchema serializes");
90	    serde_json::from_value(value).expect("op-blob PluginSchema accepts op-state-store schema")
91	}
