    let mut schema = state_store_schema_to_blob_schema(schema);
    schema.name = plugin_id.to_string();
    blobify_with_identity(&schema, identity)
}

fn state_store_schema_to_blob_schema(schema: op_state_store::PluginSchema) -> PluginSchema {
    let value = serde_json::to_value(schema).expect("op-state-store PluginSchema serializes");
    serde_json::from_value(value).expect("op-blob PluginSchema accepts op-state-store schema")
}

